// Hand-edited. NOT regenerated by `npm run refresh-live`.
//
// Coverage rails for the live cohort comparison view.
//   MIN_N_GLOBAL    — below this, the header "Compare to live cohort" toggle
//                     is disabled.
//   MIN_N_PER_BUCKET — per-trigger / per-objection-category / per-vertical-cell.
//                     Below this, the live value renders muted with a "Low n"
//                     pill and no DeltaBadge.
//
// Tune as the live cohort grows or shrinks.
export const MIN_N_GLOBAL = 20;
export const MIN_N_PER_BUCKET = 5;

// Delta below this many percentage points renders gray (not significant).
export const DELTA_SIGNIFICANCE_PP = 5;
